CREATE TABLE PORTAL_COMERCIAL.dbo.PDV_RECUPERO (
	id int IDENTITY(1,1) NOT NULL,
	DNI_RESPONSABLE int NOT NULL,
	fecha_inicio date NOT NULL,
	fecha_fin date NOT NULL,
	created_at datetime DEFAULT getdate() NOT NULL,
	CONSTRAINT PK_PDV_RECUPERO PRIMARY KEY (id)
);

-- Índices
CREATE INDEX idx_dni ON PORTAL_COMERCIAL.dbo.PDV_RECUPERO (DNI_RESPONSABLE);
CREATE INDEX idx_fechas ON PORTAL_COMERCIAL.dbo.PDV_RECUPERO (fecha_inicio, fecha_fin);

-- Insert 10 al 12 febrero 2026

-- Excluir estos PDV del flyer cargado (mismo periodo 10-12 feb 2026)
DELETE FROM PORTAL_COMERCIAL.dbo.PDV_OUT_FLYERS
WHERE fecha_inicio = '2026-02-10' AND fecha_fin = '2026-02-12'
  AND CAST(dni_responsable AS int) IN (
    SELECT DNI_RESPONSABLE
    FROM PORTAL_COMERCIAL.dbo.PDV_RECUPERO
    WHERE fecha_inicio = '2026-02-10' AND fecha_fin = '2026-02-12'
  );

-- Insert 13 al 16 febrero 2026

-- Insert 18 al 21 febrero 2026

-- Solo se eliminan flyers que NO digan "recupera" (incentivos normales) para PDV recupero 18-21 feb; se conservan RECUPERO y campañas tipo TODOS
DELETE f
FROM PORTAL_COMERCIAL.dbo.PDV_OUT_FLYERS f
WHERE f.fecha_inicio = '2026-02-18' AND f.fecha_fin = '2026-02-21'
  AND CAST(f.dni_responsable AS int) IN (
    SELECT DNI_RESPONSABLE
    FROM PORTAL_COMERCIAL.dbo.PDV_RECUPERO
    WHERE fecha_inicio = '2026-02-18' AND fecha_fin = '2026-02-21'
  )
  AND NOT (
    EXISTS (
      SELECT 1
      FROM PORTAL_COMERCIAL.dbo.PDV_OUT_CAMPAÑAS_FLYERS c
      WHERE c.foto_esquema = f.foto_esquema
        AND c.fecha_inicio = f.fecha_inicio
        AND c.fecha_fin = f.fecha_fin
        AND UPPER(LTRIM(RTRIM(ISNULL(c.criterio_filtro, '')))) = 'RECUPERO'
    )
    OR UPPER(ISNULL(f.tipoImg, '')) LIKE '%RECUPERA%'
    OR UPPER(ISNULL(f.foto_esquema, '')) LIKE '%RECUPERA%'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM PORTAL_COMERCIAL.dbo.PDV_OUT_CAMPAÑAS_FLYERS c
    WHERE c.foto_esquema = f.foto_esquema
      AND c.fecha_inicio = f.fecha_inicio
      AND c.fecha_fin = f.fecha_fin
      AND UPPER(LTRIM(RTRIM(ISNULL(c.modo, '')))) = 'TODOS'
  );
